import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";
import { onTerminalLifecycle, onTerminalOutput } from "./tauri";
import { TerminalOutputDecoderRegistry } from "./terminalOutput";

const MAX_BACKLOG_CHARS = 512 * 1024;
const MAX_OSC_TITLE_CHARS = 8 * 1024;
const OSC_TITLE_START_RE = /\u001b\](?:0|1|2);/g;
const OSC_PARTIAL_PREFIXES = ["\u001b", "\u001b]", "\u001b]0", "\u001b]1", "\u001b]2"] as const;

type OutputListener = (text: string) => void;
type LifecycleListener = (payload: TerminalLifecyclePayload) => void;
type TitleListener = (sessionId: string, title: string) => void;

type SessionBacklog = {
  chunks: string[];
  totalChars: number;
};

export type OscTitleScanResult = {
  titles: string[];
  carry: string;
};

/**
 * Extracts OSC 0/1/2 terminal titles from decoded PTY output while preserving an incomplete
 * sequence for the next chunk. This runs independently of xterm, so background/unmounted tabs
 * still produce activity title updates.
 */
export function scanTerminalOscTitles(text: string, carry = ""): OscTitleScanResult {
  const source = `${carry}${text}`;
  const titles: string[] = [];
  let searchFrom = 0;

  OSC_TITLE_START_RE.lastIndex = 0;
  while (true) {
    OSC_TITLE_START_RE.lastIndex = searchFrom;
    const match = OSC_TITLE_START_RE.exec(source);
    if (!match) break;

    const valueStart = match.index + match[0].length;
    const terminator = findOscTerminator(source, valueStart);
    if (!terminator) {
      return {
        titles,
        carry: source.slice(Math.max(match.index, source.length - MAX_OSC_TITLE_CHARS)),
      };
    }

    titles.push(source.slice(valueStart, terminator.index));
    searchFrom = terminator.index + terminator.length;
  }

  return { titles, carry: findPartialOscPrefix(source.slice(searchFrom)) };
}

function findOscTerminator(source: string, from: number): { index: number; length: number } | null {
  const candidates = [
    { index: source.indexOf("\u0007", from), length: 1 },
    { index: source.indexOf("\u001b\\", from), length: 2 },
    { index: source.indexOf("\u009c", from), length: 1 },
  ].filter((candidate) => candidate.index >= 0);
  if (candidates.length === 0) return null;
  return candidates.reduce((earliest, candidate) => candidate.index < earliest.index ? candidate : earliest);
}

function findPartialOscPrefix(source: string): string {
  for (const prefix of [...OSC_PARTIAL_PREFIXES].sort((a, b) => b.length - a.length)) {
    if (source.endsWith(prefix)) return prefix;
  }
  return "";
}

class TerminalEventBus {
  private readonly decoderRegistry = new TerminalOutputDecoderRegistry();
  private readonly outputListeners = new Map<string, Set<OutputListener>>();
  private readonly lifecycleListeners = new Set<LifecycleListener>();
  private readonly titleListeners = new Set<TitleListener>();
  private readonly backlog = new Map<string, SessionBacklog>();
  private readonly titleCarry = new Map<string, string>();
  private readonly lastTitle = new Map<string, string>();
  private startPromise: Promise<void> | null = null;

  ensureStarted(): Promise<void> {
    if (this.startPromise) return this.startPromise;
    this.startPromise = Promise.all([
      onTerminalOutput((payload) => this.handleOutput(payload)),
      onTerminalLifecycle((payload) => this.handleLifecycle(payload)),
    ]).then(() => undefined);
    return this.startPromise;
  }

  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
    listeners.add(listener);
    this.outputListeners.set(sessionId, listeners);

    if (replay) {
      const existing = this.backlog.get(sessionId);
      if (existing && existing.totalChars > 0) {
        listener(existing.chunks.join(""));
      }
    }

    return () => {
      const current = this.outputListeners.get(sessionId);
      current?.delete(listener);
      if (current?.size === 0) this.outputListeners.delete(sessionId);
    };
  }

  subscribeLifecycle(listener: LifecycleListener) {
    this.lifecycleListeners.add(listener);
    return () => {
      this.lifecycleListeners.delete(listener);
    };
  }

  subscribeTitle(listener: TitleListener) {
    this.titleListeners.add(listener);
    return () => {
      this.titleListeners.delete(listener);
    };
  }

  clearSession(sessionId: string) {
    this.decoderRegistry.reset(sessionId);
    this.backlog.delete(sessionId);
    this.outputListeners.delete(sessionId);
    this.titleCarry.delete(sessionId);
    this.lastTitle.delete(sessionId);
  }

  getBacklogMetricsForTest(sessionId?: string): { sessions: number; chunks: number; chars: number } {
    if (sessionId) {
      const entry = this.backlog.get(sessionId);
      if (!entry) return { sessions: 0, chunks: 0, chars: 0 };
      return {
        sessions: 1,
        chunks: entry.chunks.length,
        chars: entry.totalChars,
      };
    }
    let totalChunks = 0;
    let totalChars = 0;
    for (const entry of this.backlog.values()) {
      totalChunks += entry.chunks.length;
      totalChars += entry.totalChars;
    }
    return {
      sessions: this.backlog.size,
      chunks: totalChunks,
      chars: totalChars,
    };
  }

  private handleOutput(payload: TerminalOutputPayload) {
    const text = this.decoderRegistry.decode(payload.sessionId, payload.data);
    if (text) this.publishOutput(payload.sessionId, text);
  }

  private handleLifecycle(payload: TerminalLifecyclePayload) {
    if (payload.state === "exited" || payload.state === "failed") {
      const tail = this.decoderRegistry.finish(payload.sessionId);
      if (tail) this.publishOutput(payload.sessionId, tail);
    }
    for (const listener of this.lifecycleListeners) listener(payload);
  }

  private publishOutput(sessionId: string, text: string) {
    const scan = scanTerminalOscTitles(text, this.titleCarry.get(sessionId) ?? "");
    if (scan.carry) this.titleCarry.set(sessionId, scan.carry);
    else this.titleCarry.delete(sessionId);

    for (const title of scan.titles) {
      if (this.lastTitle.get(sessionId) === title) continue;
      this.lastTitle.set(sessionId, title);
      for (const listener of this.titleListeners) listener(sessionId, title);
    }

    if (text.length > 0) {
      let entry = this.backlog.get(sessionId);
      if (!entry) {
        entry = { chunks: [], totalChars: 0 };
        this.backlog.set(sessionId, entry);
      }

      entry.chunks.push(text);
      entry.totalChars += text.length;

      while (entry.totalChars > MAX_BACKLOG_CHARS && entry.chunks.length > 0) {
        const oldest = entry.chunks[0];
        if (oldest === undefined) break;
        const overflow = entry.totalChars - MAX_BACKLOG_CHARS;
        if (oldest.length <= overflow) {
          entry.chunks.shift();
          entry.totalChars -= oldest.length;
        } else {
          entry.chunks[0] = oldest.slice(overflow);
          entry.totalChars -= overflow;
          break;
        }
      }
    }

    for (const listener of this.outputListeners.get(sessionId) ?? []) listener(text);
  }
}

export const terminalEventBus = new TerminalEventBus();

export function getBacklogMetricsForTest(sessionId?: string) {
  return terminalEventBus.getBacklogMetricsForTest(sessionId);
}

export function ensureTerminalEvents() {
  return terminalEventBus.ensureStarted();
}

declare global {
  interface Uint8ArrayConstructor {
    fromBase64?(data: string, options?: { readonly alphabet?: "base64" | "base64url" }): Uint8Array;
  }
}

export function decodeBase64(data: string): Uint8Array {
  if (typeof Uint8Array.fromBase64 === "function") {
    return Uint8Array.fromBase64(data);
  }
  if (typeof Buffer !== "undefined") {
    const buffer = Buffer.from(data, "base64");
    return new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
  }
  const binary = globalThis.atob(data);
  return Uint8Array.from(binary, (char) => char.codePointAt(0) ?? 0);
}

export class TerminalOutputDecoderRegistry {
  private readonly decoders = new Map<string, TextDecoder>();

  decode(sessionId: string, base64Data: string): string {
    const decoder = this.getDecoder(sessionId);
    return decoder.decode(decodeBase64(base64Data), { stream: true });
  }

  finish(sessionId: string): string {
    const decoder = this.decoders.get(sessionId);
    if (!decoder) return "";
    this.decoders.delete(sessionId);
    return decoder.decode();
  }

  reset(sessionId: string): void {
    this.decoders.delete(sessionId);
  }

  clear(): void {
    this.decoders.clear();
  }

  private getDecoder(sessionId: string): TextDecoder {
    const existing = this.decoders.get(sessionId);
    if (existing) return existing;
    const decoder = new TextDecoder("utf-8", { fatal: false });
    this.decoders.set(sessionId, decoder);
    return decoder;
  }
}

import type { FitAddon } from "@xterm/addon-fit";
import type { SearchAddon } from "@xterm/addon-search";
import type { Terminal } from "@xterm/xterm";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "./tauri";
import { terminalEventBus } from "./terminalEvents";
import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  applyTerminalSettings,
  FALLBACK_PREFERENCES,
  fetchCachedNativePreferences,
  loadTerminalSettings,
  resolveTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type TerminalInstance = {
  element: HTMLDivElement;
  terminal: Terminal;
  fitAddon: FitAddon;
  searchAddon: SearchAddon;
  disposeWebgl: () => void;
  resizeObserver: ResizeObserver;
  disposables: Array<() => void>;
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  unsubscribeOutput?: () => void;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const spawnPromise = this.createInstance(session, active, onBell, onTitleChange);
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      this.instances.set(session.id, instance);
      return instance;
    } finally {
      this.pendingSpawns.delete(session.id);
    }
  }

  private async createInstance(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const hostElement = document.createElement("div");
    hostElement.className = "terminal-host h-full w-full bg-terminal";
    hostElement.setAttribute("aria-label", `Terminal in ${session.cwd}`);
    Object.assign(hostElement.style, {
      position: "absolute",
      inset: "0px",
      width: "100%",
      height: "100%",
      minWidth: "0px",
      minHeight: "0px",
      overflow: "hidden",
    });

    const [latestNativePrefs, { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor, Unicode11Addon, SearchAddon: SearchAddonConstructor }] =
      await Promise.all([
        Promise.race([
          fetchCachedNativePreferences(),
          new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
            setTimeout(() => resolve(FALLBACK_PREFERENCES), 200),
          ),
        ]),
        loadTerminalAssets(),
      ]);

    const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

    const terminal = new TerminalConstructor({
      allowProposedApi: false,
      customGlyphs: false,
      convertEol: true,
      cursorBlink: true,
      cursorStyle: finalSettings.cursorStyle ?? "block",
      fontFamily: finalSettings.fontFamily,
      fontSize: finalSettings.fontSize,
      lineHeight: 1.0,
      letterSpacing: 0,
      macOptionIsMeta: finalSettings.macosOptionAsAlt,
      scrollback: finalSettings.scrollback,
      theme: finalSettings.theme,
    });
    const fitAddon = new FitAddonConstructor();
    terminal.loadAddon(fitAddon);
    const searchAddon = new SearchAddonConstructor();
    terminal.loadAddon(searchAddon);
    if (Unicode11Addon) {
      try {
        const unicode11Addon = new Unicode11Addon();
        terminal.loadAddon(unicode11Addon);
        terminal.unicode.activeVersion = "11";
      } catch {
      }
    }
    terminal.open(hostElement);

    let disposeWebgl: () => void = () => undefined;
    void attachWebglRenderer(terminal).then((dispose) => {
      disposeWebgl = dispose;
    });

    let resizeFrame = 0;
    const resize = () => {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(() => {
        if (hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
        fitAddon.fit();
        const backendSessionId = session.backendSessionId;
        if (!backendSessionId) return;
        void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
      });
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(hostElement);

    const disposables: Array<() => void> = [];

    const dataDisposable = terminal.onData((data) => {
      const backendSessionId = session.backendSessionId;
      if (!backendSessionId) return;
      void writeTerminal({ sessionId: backendSessionId, data }).catch(() => undefined);
    });
    disposables.push(() => dataDisposable.dispose());

    const titleDisposable = terminal.onTitleChange((title) => {
      this.instances.get(session.id)?.onTitleChange?.(title);
    });
    disposables.push(() => titleDisposable.dispose());

    const bellDisposable = terminal.onBell(() => {
      this.instances.get(session.id)?.onBell?.();
    });
    disposables.push(() => bellDisposable.dispose());

    const focusTerminal = () => terminal.focus();
    hostElement.addEventListener("pointerdown", focusTerminal);
    disposables.push(() => hostElement.removeEventListener("pointerdown", focusTerminal));

    let unsubscribeOutput: (() => void) | undefined;
    if (session.backendSessionId) {
      unsubscribeOutput = terminalEventBus.subscribeOutput(session.backendSessionId, (text) => {
        terminal.write(text);
      });
    }

    if (!isTauriRuntime()) {
      terminal.writeln("\x1b[1;32mFerryx\x1b[0m  UI preview");
      terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
      terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
    }

    resize();
    if (active) terminal.focus();

    return {
      element: hostElement,
      terminal,
      fitAddon,
      searchAddon,
      disposeWebgl,
      resizeObserver,
      disposables,
      session,
      active,
      onBell,
      onTitleChange,
      unsubscribeOutput,
    };
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      if (session.backendSessionId !== prevBackendId) {
        inst.unsubscribeOutput?.();
        inst.unsubscribeOutput = undefined;
        if (session.backendSessionId) {
          inst.unsubscribeOutput = terminalEventBus.subscribeOutput(session.backendSessionId, (text) => {
            inst.terminal.write(text);
          });
        }
      }
    }
  }

  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  destroy(sessionId: string) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      inst.resizeObserver.disconnect();
      inst.unsubscribeOutput?.();
      for (const d of inst.disposables) d();
      inst.searchAddon.dispose();
      inst.disposeWebgl();
      inst.terminal.dispose();
      inst.element.remove();
    }
  }
}

export const terminalHostManager = new TerminalHostManager();

use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use tokio::sync::broadcast;

const DEFAULT_BUFFER_CAPACITY: usize = 512 * 1024; // 512 KiB
const BROADCAST_CAPACITY: usize = 1024;

pub struct BoundedBuffer {
    capacity: usize,
    chunks: VecDeque<Vec<u8>>,
    current_size: usize,
}

impl BoundedBuffer {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            chunks: VecDeque::new(),
            current_size: 0,
        }
    }

    pub fn push(&mut self, chunk: Vec<u8>) {
        if chunk.is_empty() {
            return;
        }
        self.current_size += chunk.len();
        self.chunks.push_back(chunk);

        while self.current_size > self.capacity && !self.chunks.is_empty() {
            if let Some(front) = self.chunks.pop_front() {
                self.current_size -= front.len();
            }
        }
    }

    pub fn snapshot(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.current_size);
        for chunk in &self.chunks {
            out.extend_from_slice(chunk);
        }
        out
    }
}

struct SessionHub {
    buffer: BoundedBuffer,
    sender: broadcast::Sender<Vec<u8>>,
}

#[derive(Clone)]
pub struct TerminalOutputHub {
    sessions: Arc<RwLock<HashMap<String, Arc<RwLock<SessionHub>>>>>,
    capacity: usize,
}

impl Default for TerminalOutputHub {
    fn default() -> Self {
        Self::new(DEFAULT_BUFFER_CAPACITY)
    }
}

impl TerminalOutputHub {
    pub fn new(capacity: usize) -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            capacity,
        }
    }

    pub fn register_session(&self, session_id: &str) -> broadcast::Receiver<Vec<u8>> {
        let (tx, rx) = broadcast::channel(BROADCAST_CAPACITY);
        let hub = SessionHub {
            buffer: BoundedBuffer::new(self.capacity),
            sender: tx,
        };
        self.sessions
            .write()
            .insert(session_id.to_string(), Arc::new(RwLock::new(hub)));
        rx
    }

    pub fn publish(&self, session_id: &str, chunk: Vec<u8>) {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        };

        if let Some(hub) = session_hub {
            let mut hub = hub.write();
            hub.buffer.push(chunk.clone());
            // It is okay if there are no active receivers; send returns Err in that case
            let _ = hub.sender.send(chunk);
        }
    }

    pub fn subscribe(&self, session_id: &str) -> Option<(Vec<u8>, broadcast::Receiver<Vec<u8>>)> {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        }?;

        let hub = session_hub.read();
        let history = hub.buffer.snapshot();
        let rx = hub.sender.subscribe();
        Some((history, rx))
    }

    pub fn remove_session(&self, session_id: &str) {
        self.sessions.write().remove(session_id);
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_output_hub_replay_and_broadcast() {
        let hub = TerminalOutputHub::new(1024);
        let session_id = "test-session";
        let _initial_rx = hub.register_session(session_id);

        hub.publish(session_id, b"hello ".to_vec());
        hub.publish(session_id, b"world\n".to_vec());

        let (history, mut rx) = hub.subscribe(session_id).expect("session exists");
        assert_eq!(history, b"hello world\n");

        hub.publish(session_id, b"live chunk".to_vec());
        let received = rx.recv().await.expect("received live message");
        assert_eq!(received, b"live chunk");
    }

    #[tokio::test]
    async fn test_bounded_buffer_overflow() {
        let mut buffer = BoundedBuffer::new(10);
        buffer.push(b"12345".to_vec());
        buffer.push(b"67890".to_vec());
        buffer.push(b"abcdef".to_vec());

        let snap = buffer.snapshot();
        assert!(snap.len() <= 16); // pops chunks until under capacity
        assert!(snap.ends_with(b"abcdef"));
    }
}

use crate::terminal::output_hub::TerminalOutputHub;
use crate::terminal::{PtyError, PtyManager, PtySession, TerminalSignal};
use crate::worktree::manager::WorktreeManager;
use portable_pty::CommandBuilder;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    output_hub: Arc<TerminalOutputHub>,
}

impl Default for TerminalService {
    fn default() -> Self {
        Self::new(
            Arc::new(PtyManager::new()),
            Arc::new(TerminalOutputHub::default()),
        )
    }
}

impl TerminalService {
    pub fn new(pty_manager: Arc<PtyManager>, output_hub: Arc<TerminalOutputHub>) -> Self {
        Self {
            pty_manager,
            output_hub,
        }
    }

    pub fn pty_manager(&self) -> &Arc<PtyManager> {
        &self.pty_manager
    }

    pub fn output_hub(&self) -> &Arc<TerminalOutputHub> {
        &self.output_hub
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, broadcast::Receiver<Vec<u8>>), PtyError> {
        let (session_id, mut pty_rx) =
            self.pty_manager
                .spawn_in_worktree(cmd, cols, rows, worktree_manager, worktree_path)?;

        let broadcast_rx = self.output_hub.register_session(&session_id);

        // Spawn output pump task from PTY reader to OutputHub
        let output_hub = Arc::clone(&self.output_hub);
        let session_id_clone = session_id.clone();
        tokio::spawn(async move {
            while let Some(chunk) = pty_rx.recv().await {
                output_hub.publish(&session_id_clone, chunk);
            }
        });

        Ok((session_id, broadcast_rx))
    }

    pub fn attach(
        &self,
        session_id: &str,
    ) -> Result<(Vec<u8>, broadcast::Receiver<Vec<u8>>), PtyError> {
        if !self
            .pty_manager
            .list_sessions()
            .contains(&session_id.to_string())
        {
            return Err(PtyError::SessionNotFound(session_id.to_string()));
        }

        self.output_hub
            .subscribe(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        self.pty_manager.write_input(session_id, data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        self.pty_manager.resize(session_id, cols, rows)
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        self.pty_manager.signal(session_id, signal)
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        self.output_hub.remove_session(session_id);
        self.pty_manager.close_session(session_id).await
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.pty_manager.list_sessions()
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.pty_manager.get_session(session_id)
    }
}

